# ShopStack edge gateway (known-good baseline, version 1)
worker_processes 1;
events { worker_connections 512; }
http {
  log_format main '$time_iso8601 gateway $status $request_method $uri upstream=$upstream_addr rt=$request_time';
  access_log /dev/stdout main;
  error_log /dev/stderr warn;

  upstream shop_api {
    server api:8001;
  }

  server {
    listen 80;
    location = /healthz { return 200 "ok\n"; }
    location /api/ {
      proxy_pass http://shop_api;
      proxy_connect_timeout 2s;
      proxy_read_timeout 5s;
    }
    location / { return 404; }
  }
}

